import type { ConsultationPayload, Project, Service } from "@/types/api";

const baseUrl = (process.env.NEXT_PUBLIC_API_BASE_URL ?? "http://127.0.0.1:8000").replace(/\/$/, "");

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(`${baseUrl}${path}`, { ...init, headers: { "Content-Type": "application/json", ...init?.headers }, cache: "no-store" });
  if (!response.ok) throw new Error("تعذر الاتصال بالخدمة. يرجى المحاولة مرة أخرى.");
  return response.json() as Promise<T>;
}

export const api = {
  services: () => request<Service[]>("/api/services/"),
  projects: () => request<Project[]>("/api/projects/"),
  consultation: (payload: ConsultationPayload) => request<ConsultationPayload>("/api/consultation/", { method: "POST", body: JSON.stringify(payload) }),
  mediaUrl: (image: string | null) => image ? (image.startsWith("http") ? image : `${baseUrl}${image}`) : null,
};
