import type { Service } from "@/types/api";
export function ServicesList({services}:{services:Service[]}){if(!services.length)return <p className="py-8 text-stone-600">لا توجد خدمات منشورة حالياً.</p>;return <div className="border-t border-black/20">{services.map((service,i)=><article key={service.id} className="group grid gap-4 border-b border-black/20 py-7 md:grid-cols-[80px_1fr_2fr]"><span className="eyebrow">{String(i+1).padStart(2,"0")}</span><h3 className="text-2xl font-bold transition group-hover:text-[#52604d]">{service.name}</h3><p className="max-w-xl leading-7 text-black/70">{service.description}</p></article>)}</div>}
